import math
from numbers import Real


def average_present(values):
    total = 0.0
    count = 0
    for value in values:
        if value is None:
            continue
        if isinstance(value, bool) or not isinstance(value, Real):
            raise TypeError("values must be finite real numbers or None")
        value = float(value)
        if not math.isfinite(value):
            raise TypeError("values must be finite real numbers or None")
        total += value
        count += 1
    return total / count

